// src/components/AgendaDayDetails.jsx
// Lista de itens de um dia de agenda — read-only.
// Recebe um daySummary de getAgendaDaySummary (agendaEngine.js).

import React from "react";
import { estimateTaskMinutes } from "../core/agendaEngine";

const TYPE_LABELS = {
  relearning:  "Releitura",
  overdue:     "Atrasado",
  review:      "Revisão",
  d0_critical: "Novo — Crítico",
  new_topic:   "Novo tópico",
  simulation:  "Simulado",
  weekly:      "Revisão semanal",
};

const TYPE_COLORS = {
  relearning:  "border-purple-500/30 bg-purple-500/10 text-purple-300",
  overdue:     "border-red-500/30 bg-red-500/10 text-red-300",
  review:      "border-blue-500/20 bg-blue-500/10 text-blue-300",
  d0_critical: "border-amber-500/30 bg-amber-500/10 text-amber-300",
  new_topic:   "border-green-500/20 bg-green-500/10 text-green-300",
  simulation:  "border-sky-500/20 bg-sky-500/10 text-sky-300",
  weekly:      "border-white/10 bg-white/5 text-gray-300",
};

function StepBadge({ stepKey, phase }) {
  const label = phase === "relearning" ? "Releitura" : (stepKey || "").toUpperCase();
  return (
    <span className="text-[9px] font-bold text-gray-500 uppercase tracking-wide">{label}</span>
  );
}

export default function AgendaDayDetails({ daySummary }) {
  if (!daySummary || daySummary.isEmpty) return null;

  const { date, items, totalMinutes, overdueCount, newCount } = daySummary;
  const [, m, d] = (date || "").split("-");
  const dateLabel = date ? `${d}/${m}` : "";

  return (
    <div className="rounded-2xl border border-white/10 bg-[#0f0f19] p-4 space-y-3">
      {/* Cabeçalho do dia */}
      <div className="flex items-center justify-between">
        <h4 className="text-[12px] font-black text-white">
          Agenda — {dateLabel}
        </h4>
        <div className="flex items-center gap-2 text-[10px] text-gray-500">
          {overdueCount > 0 && (
            <span className="text-red-400 font-bold">{overdueCount} atrasado{overdueCount > 1 ? "s" : ""}</span>
          )}
          {newCount > 0 && (
            <span className="text-green-400 font-bold">{newCount} novo{newCount > 1 ? "s" : ""}</span>
          )}
          <span>{totalMinutes} min</span>
        </div>
      </div>

      {/* Lista de itens */}
      <div className="space-y-2">
        {items.map((item) => {
          const typeColor = TYPE_COLORS[item.type] || TYPE_COLORS.review;
          const typeLabel = TYPE_LABELS[item.type] || item.type;
          const mins = estimateTaskMinutes(item);

          return (
            <div
              key={item.id}
              className={`rounded-xl border p-3 space-y-1 ${typeColor}`}
            >
              <div className="flex items-start justify-between gap-2">
                <div className="flex-1 min-w-0">
                  <p className="text-[12px] font-bold leading-snug truncate">
                    {item.temaNome || "Tópico"}
                  </p>
                  <div className="flex items-center gap-2 mt-0.5">
                    <span className="text-[10px] opacity-70">{item.area}</span>
                    {item.stepKey && <StepBadge stepKey={item.stepKey} phase={item.phase} />}
                  </div>
                </div>
                <div className="text-right shrink-0">
                  <p className="text-[10px] font-bold opacity-80">{typeLabel}</p>
                  <p className="text-[10px] opacity-60">{mins} min</p>
                </div>
              </div>
            </div>
          );
        })}
      </div>

      <p className="text-[10px] text-gray-600 text-center">
        Estude pelo Dashboard ou Modo Foco — a agenda é somente visualização.
      </p>
    </div>
  );
}
